router = APIRouter(prefix="/projects", tags=["projects"])


@router.get("")
def list_projects(user: CurrentUser, session: SessionDep) -> list[ProjectListItem]:
    """The projects you are a member of, by id, with their task counts."""
    return projects.list_projects(session, user)


@router.post("", status_code=status.HTTP_201_CREATED)
def create_project(
    data: ProjectCreate, user: CurrentUser, session: SessionDep, clock: ClockDep, response: Response
) -> ProjectOut:
    project = projects.create_project(session, user, data, clock=clock)
    response.headers["Location"] = f"/v1/projects/{project.id}"
    return ProjectOut.of(project)


@router.get("/{project_id}")
def read_project(access: ProjectReader, session: SessionDep) -> ProjectOut:
    return ProjectOut.of(projects.with_members(session, access.project))

@router.post("/projects/{project_id}/tasks", status_code=status.HTTP_201_CREATED)
def create_task(
    access: ProjectMember,
    data: TaskCreate,
    session: SessionDep,
    clock: ClockDep,
    response: Response,
) -> TaskOut:
    task = tasks.create_task(session, access.project, data, clock=clock)
    response.headers["Location"] = f"/v1/tasks/{task.id}"
    response.headers["ETag"] = task.etag
    return TaskOut.model_validate(task)

def _check_assignee(session: Session, project: Project, assignee_id: int) -> User:
    assignee = users.get(session, assignee_id)
    if assignee is None or projects.role_of(session, project.id, assignee_id) is None:
        raise Unprocessable(
            f"user {assignee_id} is not a member of this project",
            errors={"assignee_id": "must be a member of the project"},
        )
    return assignee


def _check_due_on(project: Project, due_on: date, *, today: date) -> None:
    if due_on < today:
        raise Unprocessable(
            f"{due_on} is in the past (today is {today})",
            errors={"due_on": f"must be {today} or later"},
        )
    if project.start_date is not None and due_on < project.start_date:
        raise DueBeforeProjectStart(
            f"the project starts on {project.start_date}, after {due_on}",
            errors={"due_on": f"must be on or after the project's start, {project.start_date}"},
        )

